REFERENCES = [np.asarray(row["features"], dtype=np.float64) for row in REFERENCE_ROWS]

st.info("ارفع محاولة جديدة مدتها 3–8 ثوانٍ، مع ظهور اليد كاملة وخلفية واضحة.")
with st.form("video_test_form"):
    upload = st.file_uploader("فيديو المحاولة", type=["mp4", "mov", "avi", "m4v"])
    submitted = st.form_submit_button("تحليل الإشارة", type="primary")

if submitted:
    if upload is None:
        st.error("اختر فيديو أولًا.")
    elif upload.size > 25_000_000:
        st.error("حجم الفيديو أكبر من 25MB. استخدم مقطعًا أقصر.")
    else:
        temp_path = None
        try:
            suffix = Path(upload.name).suffix or ".mp4"
            with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as temporary:
                temporary.write(upload.getvalue())
                temp_path = Path(temporary.name)
            with st.spinner("جارٍ استخراج حركة اليد ومقارنتها بالمراجع..."):
                attempt, detection = extract_video_sequence(
                    temp_path, sample_fps=6.0, max_seconds=8.0
                )
                candidates = [match_sequence(attempt, reference) for reference in REFERENCES]
                best = max(candidates, key=lambda item: item["score"])
            a, b, c = st.columns(3)
            a.metric("الإشارة", "السلام عليكم")
            b.metric("درجة المطابقة", f'{best["score"]:.1f}%')
            c.metric("اكتشاف اليد", f'{detection["detection_rate"]:.1f}%')
            st.progress(int(best["score"]))
            if best["score"] >= 65:
                st.success("تم التعرف على إشارة «السلام عليكم» كمطابقة أولية.")
            else:
                st.warning("المحاولة لا تطابق المراجع بما يكفي. أظهر اليد كاملة وأعد الحركة بوضوح.")
            st.caption(
                f'عدد المراجع: {len(REFERENCES)} · لقطات اليد: {detection["detected_frames"]} · '
                "لا يُحفظ الفيديو الخام."
            )
        except Exception as exc:
            st.error(f"تعذّر تحليل الفيديو: {exc}")
        finally:
            if temp_path is not None:
                temp_path.unlink(missing_ok=True)

st.divider()
